-- 174: Original BrillaPrep WASSCE BrillaPrep transitional Metalwork beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_174_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_174_guard;
INSERT INTO _migration_174_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_011' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_3' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which feature distinguishes steel from commercially pure iron in ordinary workshop use?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Steel contains no iron","B. Pure iron is always harder than tool steel","C. Controlled carbon and alloy content gives a wider range of strength and hardness","D. Steel cannot be heat treated"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Carbon and other alloying elements change the iron structure, enabling steels to achieve properties suited to tools and engineering parts. Therefore the correct answer is C: Controlled carbon and alloy content gives a wider range of strength and hardness.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_011' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_174_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_012' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_3' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is annealing applied to a work-hardened metal?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Make it maximally brittle for forming","B. Coat it with a corrosion-resistant metal","C. Increase dimensions without heating","D. Soften it, relieve internal stress and restore ductility"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Heating to an appropriate temperature followed by controlled cooling permits structural recovery and makes further forming or machining easier. Therefore the correct answer is D: Soften it, relieve internal stress and restore ductility.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_012' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_174_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_013' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_3' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of tempering hardened carbon steel?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Reduce brittleness while retaining useful hardness","B. Remove all carbon from the steel","C. Melt the steel below room temperature","D. Convert it into a non-metallic material"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Reheating hardened steel below its critical range adjusts the martensitic structure, trading some hardness for toughness and service reliability. Therefore the correct answer is A: Reduce brittleness while retaining useful hardness.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_013' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_174_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_014' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_3' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which property is most important for a material that must absorb impact without fracturing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Brittleness","B. Toughness","C. Electrical resistance only","D. Low melting point"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Tough materials absorb energy through elastic and plastic deformation before fracture, which is essential under shock loading. Therefore the correct answer is B: Toughness.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_014' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_174_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_metalwork_b003_015' AND NOT (q.topic_id IS 'topic_was_metalwork_b003_3' AND q.subject_id IS 'subj_wassce_metalwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is aluminium widely used where low component mass is important?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It is denser than lead","B. It cannot conduct heat","C. It has relatively low density with useful corrosion resistance","D. It is always harder than hardened steel"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Aluminium alloys combine low density with practical strength and a protective oxide film, making them valuable in weight-sensitive products. Therefore the correct answer is C: It has relatively low density with useful corrosion resistance.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_metalwork_b003_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_metalwork_b003_015' AND NOT (r.batch_id IS 'wassce-craft-beta-003' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Metalwork practice aligned to WAEC Ghana catalogue and examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
